import { createSlice } from "@reduxjs/toolkit";

 const initalState={
    currentUser:null,
    loading:false,
    error:false,
 }

 const userSlice=createSlice({
    name:'user',
    initalState,
    reducers:{
        signInStart:(state)=>{
            state.loading=true;
        },
        signInSuccess:(state,action)=>{
            state.currentUser=action.payload;
            state.loading=false;
            state.error=false;
        },
        signInFailour:(state,action)=>{
            state.loading=false;
            state.error=action.payload
        }
    }
 })

 export const{signInSuccess,signInFailour,signInStart}=userSlice.actions;
 
 export default userSlice.reducer;
